// SC's test: the two ends the scene sets level — the held passage's first
// shared stretch and its counterpart, a far end as the opener names it, the
// first pair with nothing held, the second pane at its top with nothing
// shared, nothing of a document a far end names whole — and the runs the
// bands are drawn from, joined only where they adjoin in both documents;
// each band at its extent on each pane's facing edge — two bands sharing a
// line dividing it at its middle, a difference taking a whole line an
// unbanded stretch, runs in another order crossing, an identity held twice
// sharing nothing, every run a band — and the strokes where runs consecutive
// in both documents meet on both sides: an in-line insertion a half stroke
// on its side, two changes in one line one stroke counting 2, a change
// across a line break taking no whole line a stroke at the edge between the
// lines, each named by its changes' characters on each side through the
// item rule; a band's ground and edges, clipped with the stub's triangle,
// and a stroke's half as drawn (FP-26); a passage's counterpart
// and counterparts, clipped to the passage in the first document's order,
// and the position two versions share nearest a passage the second holds
// none of (FP-22); the lines between the panes — one per link and pair of
// ends however the ends stand or moved, each end in the mark its pane's
// document gives the link, changing colour once at the middle of the gap, a
// whole-work end at its pane's facing edge, drawn whole in the one mark its
// ends there merge into, a floating one at its pane's first block, a far end
// where `project` places it in the version the pane holds, a line ending at
// a covered pane's cover, its head's address, which scrolls with its text
// (FP-29, FP-30) — the stop picking the next shared
// passage out of view, and the opening asking each crossing far end once;
// what the panes' runs hold of what a stop the reader left from stood for —
// the passage of pane B the stop at a band's clipped end stood for, the
// change a stroke stood for, read by bytes' identity (FP-21); the stacked
// scene — the panes standing side by side while a pane there keeps
// HEAD_CPL characters at its head and stacked a px narrower, by the face's
// rendered advance; each tie drawn at each of its ends, a band's bars joined
// by a hairline along the column; the one tie drawn whole along the column,
// the pointer's before the focus's before the link the scene was opened
// from, the pointer standing on a line's end before a stroke's before a
// band's; a whole document's end one distance below its pane's top as the
// other end below its own (FP-12, FP-26, FP-30).
// Then, against the fake port and a page of stand-ins — whose stop and
// strokes' buttons take the focus only while they stand shown, as the
// platform's do: the scene's focus —
// the plane covered while it stands, uncovered before the focus returns to
// the opener, the first opener kept across a scene opened over another, a
// focus moved out of the scene left alone (FP-20); the bar's acts named by
// their words alone, their keys exposed, and every name the scene sets and
// every word it says heard by S22's table; the scene a step on the
// trail through N-GO — its opening one entry at the act, its own close a
// Back lighting the passage it was opened from, the scene recorded as left
// and reopened so by Forward and by Back after a teleport out, the focus on
// the stop it stood on, an opening abandoned or refused giving its entry
// back, one at a link's end whose far document the board will say nothing
// of faced in the far end's words and, known so at the act, never leaving
// (FP-21, FP-25), one opened from a link's end keeping that link on its
// entry and through a Back that reopens it, the card it was opened from reopened by its close (FP-36),
// a live caret it was opened at kept by the opening and re-taken by its close (D5 K-63);
// each pane's article
// T-LAYER's mount on the inner side of its corner, its byline's facts read
// before the pane is set (FP-12, FP-34), its region named by its corner's
// first item — its kind — then its address, its corner opening with that
// kind, said once in the status region where it fills under the focus
// (FP-33, FP-36), made with the image its whole read
// asks where the page held its text with none, a copy from it named where the
// scene read its words — an edition at its bare address its member, a draft
// no member and no positions (FP-27); the opening ended by a navigation
// act's dismissal, Esc or an overlay shown, asking no `compare` after it and
// opening nothing; and a pane kept fresh by its kind (FP-23), M-PUMP started
// as the app starts it — a draft read again in place, from the reads M-PUMP
// makes of it again where the plane shows it too or an editor pane holds it,
// another's draft by the scene's own reads, an edition at its bare address
// pinned at once to the
// member its text is and set again from it, its corner's act reading
// another version in the pane's place with the passage held, a version
// counting its chain alone, a link row re-reading the text, a row writing
// an edition claim on the origin of a run a pane windows setting it again,
// a transcluded run held in a pane as one run with none of its words, its
// origin stated as lines by the plane's one rule,
// acts made while a pane reads waiting in order, the page's death keeping a pane on a text
// read as published — a draft's run in it withheld from that moment — and taking every other
// down to its cover, reading each again as a guest, and a refresh pinning an edition whose
// chain it counted past the member shown; a setting whose reads the board did not answer —
// the text, the chain, the owner's byline facts, a cause a row kept as held among them, the
// `compare` — setting nothing, the pane
// kept on its text and saying why until the read made at the daemon's running, or past the
// pause, sets it — reported kept to the one line, one place with the plane's box naming its
// address, said once as it appears and once, by what its setting changed, as it is set — and
// an opening on a text the board did not answer opening nothing; a pane's
// corner naming neither the latest version nor the chain's count while the board lags; and a
// scene opened on a document a
// far end names whole — the far pane that version or the latest, named as
// the link's whole end and current, its `compare` answering after it shows
// and adding bands alone, moving no pane and no focus (FP-20, FP-30), and so
// again as Back returns to it left from a pane or a pane's corner, the focus
// on the stop it was left from (FP-25); and a stop only that `compare` draws,
// left from and returned to — standing with the landing and taking the focus,
// its count being read, recorded again by what it stood for; answered all,
// part, none, refused or with no text to read, the focus kept and its words
// FP-21's, its kind and the line each a sentence; an act on it waiting for the
// answer, made, abandoned, or dropped
// once the reader moved on (FP-20, FP-25, FP-34); a stroke's list kept by
// its stroke's key as the reader leaves the scene and carried back by its
// reopening (FP-36); a passage the opener names by its bytes set level
// where pane A's text, as the scene reads it, places them — a landing's "read
// side by side" so setting its passage level however its source or the far
// text was set since the landing (FP-21); and a pane's byline set with its
// owner's facts as the model holds them — a facts read a row touching a doc 1
// overtook asked again before the pane is set, facts a row dropped after its
// reads read as it shows, and owner facts taken anew setting again each pane
// whose byline said other once no setting reads, a corner's act out landing
// as asked (FP-23, FP-34); and a pane's corner's acts buttons on one line of
// acts whose stop is its first — the kept word a disclosure its click opens
// and closes, in a corner opened whole too, the dispatch leaving Enter and
// Space to the button and taking an auto-repeat, ← and → walking the line
// with the scene standing, and a return to the corner landing on its stop
// (FP-20, FP-26); and a pane's kind read by the one test where the board
// does not answer its metadata — a listed edition so read at its bare
// address, its chain probed, its copy named as the plane's box names the same
// words and its versions read in its place, and an edition read again so
// still pinned at once by a newer member's arrival (FP-22, FP-23, FP-27,
// FP-39); and the moved scene's held version — derived as the scene opens on
// the draft's address, once the draft's flight has landed, from the text at
// its lines' base read from the board's history with its image, those lines
// applied, the text the page shows where it cannot be so derived — its corner
// naming what it is in the place of the kind, the kept word and the chip —
// that line, like a past state's, the corner's title in the kind's place at
// every fit, beside its column and at its document's head, held at the pane's
// top there on rows that its line's widest form at the fit takes, a
// substitution held with it, the pane named by its own element in the words
// it held when the state showed, the same at every fit, a past state's pane
// described by the line saying why it shows that state, and a hand of the
// reader's own key by its label alone (FP-26, FP-34, FP-39) — and at a
// selection in it, the
// focus there, the acts that send and a printable key giving the one reason
// the selection keys against the current text, Space keeping K-9's line
// (D6 BM-14; FP-41), and its last held line discarded, the scene staying,
// the one line naming the key that closes it as the platform draws it (D6
// BM-16; style S21). And the editor pane — a pane holding the current text
// of a draft of the person's own, whatever the camera's scale, never a past
// state or the held version: its caret keys the plane's, the pane set again
// from the text shown as typed, one live caret across two editors, ↓ and ↑
// walking a pane's span focus by span, a swallowed key answered by its
// pane's own line ending with where the person was last writing, that
// ending's act the shortest way back, the close re-taking the pane's caret
// and its anchored span, a click and a drag placing the caret by element, a
// paste, a cut, the save chord and select-all made in the pane, the undo
// chord at a step whose text the pane does not hold reading it where the step
// stands, the scene standing, and Esc's
// order there (FP-38, FP-40); its draft kept as the view's while a refresh
// reads it again, at far scale too, the pane its editor throughout — a key
// and the redo chord made at its caret at once — and the pane following the
// text shown while a setting of it reads, the setting landing on that text
// (FP-23, FP-38); and a paste's face raised in the scene
// standing while the focus stands in its draft's editor pane, whatever the
// walk under the scene stands on, written in its layer lifted over the scene
// and gone once the focus goes into another document's pane, one raised on
// the plane judged by nothing under a scene (B3-S5). And a draft's history's
// past state: refused as reclaimed, asked again where it last stood, else the
// newest kept state in its place — the draft as the board holds it, never
// asked of the board's history — under a line naming the board and the date
// of the feed's row at the floor the refusal names, else the time that state
// stood, no token left, and the list's floor mark below its row; refused
// busy, the scene opening on the newest kept state at the act and at a
// return, no face raised, and reissued — the in-flight clause after the title
// carrying the one running mark on its own busy element, the asked row
// reading, the pause doubling to its cap — until pane B is set to it in one
// step, the line said once with the clause and the landing once, no reissue
// outliving the scene; its trail entry keeping the state asked, read again by
// a return over the rows written since (FP-23,
// FP-34, FP-36); a row arriving above the state shown taking the words saying
// it is how the draft stands now from pane B's corner and its description in
// the one step that takes the row in, an older row touching neither nor any
// element of the corner (FP-20, FP-33); and the not-last clause at every fit,
// held and never folded, its title's rows never deepening, given by a row of
// the shown minute with the description and said once, its count an empty
// box until the rows below are read — read again once the board answers, to
// the feed's first position or its floor (FP-26, FP-34).
import { test, before } from 'node:test';
import assert from 'node:assert/strict';
import * as PORT from '../bridge/port.js';
import * as REC from '../model/records.js';
import * as WRITE from '../write/write.js';
import * as MACHINE from '../write/machine.js';
import * as PUMP from '../model/pump.js';
import * as F from '../model/frames.js';
import * as FAKE from '../test/fake-port.js';
import * as WALK from '../nav/walk.js';
import * as LAYER from '../text/layer.js';
import * as HOST from '../overlays/host.js';
import * as HINT from '../overlays/hint.js';
import * as FACES from '../overlays/faces.js';
import * as DELETION from '../overlays/deletion.js';
import * as FOCUS from '../nav/focus.js';
import * as KEYS from '../nav/keys.js';
import * as SCENE from './scene.js';
import * as LINE from '../line/line.js';
import { levels, merged, counterpart, counterparts, nearest, linesBetween, carriedTo, wholeEdges, drawEdge, stopFor, banded, drawBand, drawStroke, changeWords, strokeWords, sharedHeld, junctionsOf, strokeHeld, sameBytes, coverIn, heldVersionReasonOf } from './scene.js';
import { page as domPage } from '../test/dom.js';
import { byteLength } from '../util.js';
import { applyHeld } from '../model/derive.js';
import { deriveBlocks } from '../model/records.js';
import * as GO from '../nav/go.js';
import * as TRAIL from '../nav/trail.js';
import * as PAST from '../model/past.js';
import * as CAM from '../plane/camera.js';
import { accountCell } from '../plane/projection.js';
import { t, tHTML, lastRead, addressedHTML, sentence, sentences, hintSentences, heard, runsText, asRuns, fields, runningHTML } from '../strings.js';
import { esc, fingerprintCue, timeOf, dayOf } from '../util.js';
import * as LK from '../links/links.js';
import { inkOf } from '../beams/beams.js';
import { edgeStatementHTML, placeholderOf, originRunsOf, sourceStatementHTML, cornerTitle, titleRuns } from '../text/article.js';
import { HUE, NEUTRAL_HUE, VISITED_ALPHA, SAMENESS } from '../plane/register.js';
import * as ANATOMY from '../overlays/anatomy-card.js';
import * as PROV from '../overlays/provenance.js';
import * as SEL from '../overlays/selection.js';
