/**
 * The test run on `onPage`'s page with the articles the scene makes elements of the small DOM under `web/test/`, in its
 * document's tree — its selection, its ranges and its tree walkers the platform's — so a selection stands in a pane's
 * text as a drag leaves it and T-LAYER's mapping reads it as it reads the platform's; the globals that stood put back
 * after it
 * @param {(p: ReturnType<typeof page>, dom: ReturnType<typeof domPage>) => Promise<void>} body
 */
async function onPageWithText(body) {
  const dom = domPage(), g = /** @type {any} */ (globalThis), stood = { window: g.window, Node: g.Node, NodeFilter: g.NodeFilter };
  g.window = { getSelection: () => dom.document.selection, addEventListener() {} };
  g.Node = { ELEMENT_NODE: 1, TEXT_NODE: 3, DOCUMENT_NODE: 9, DOCUMENT_FRAGMENT_NODE: 11 };
  g.NodeFilter = { SHOW_ALL: 0xffffffff, SHOW_ELEMENT: 1, SHOW_TEXT: 4 };
  try {
    await onPage(async (p) => {
      const doc = /** @type {any} */ (p.doc), make = doc.createElement;
      doc.createElement = (/** @type {string} */ tag) => (tag === 'article' ? dom.document.body.appendChild(dom.document.createElement(tag)) : make(tag));
      doc.createRange = () => dom.document.createRange();
      doc.createTreeWalker = (/** @type {any} */ root, /** @type {number} */ show) => dom.document.createTreeWalker(root, show);
      try { await body(p, dom); } finally { dom.document.selection.removeAllRanges(); }
    });
  } finally { Object.assign(g, stood); }
}

/**
 * The platform's selection set over the first stretch of an article's text — its body's, never its head's — that reads
 * `words`, as a drag over them leaves it
 * @param {ReturnType<typeof domPage>} dom
 * @param {any} article
 * @param {string} words
 */
function selectWords(dom, article, words) {
  /** @type {any[]} */
  const nodes = [];
  const w = dom.document.createTreeWalker(article.querySelector('.run'), 4);
  for (let n = w.nextNode(); n; n = w.nextNode()) nodes.push(n);
  const at = nodes.map((n) => n.data).join('').indexOf(words);
  assert.ok(at >= 0, `the article reads "${words}"`);
  /** the text node and offset a character of the body's text stands at */
  const point = (/** @type {number} */ i, /** @type {boolean} */ end) => {
    let k = i;
    for (const n of nodes) { if (k < n.data.length || (end && k === n.data.length)) return [n, k]; k -= n.data.length; }
    return [nodes[nodes.length - 1], nodes[nodes.length - 1].data.length];
  };
  const [sn, so] = point(at, false), [en, eo] = point(at + words.length, true);
  dom.document.selection.set(sn, so, en, eo);
}

test('at a selection in the moved scene\'s held version, while the focus stands in it, the acts that send — Mod+K, Mod+Shift+A, Mod+Shift+C — and a printable key give the one reason the selection keys, its hint at the pane and said at every press: over the held new words, or over those and words both texts hold, that its words are not in the current text; over words the current text holds too, that they are; Space keeps K-9\'s line; with no selection there the slot\'s own reason stands, and a printable key gives the reason the span at the pane\'s focus keys, never K-9\'s line; with the focus in pane A, or the scene not the moved scene, the slot\'s own reason (issue #599, #556; D6 BM-14; B3-S2; FP-41)', () => onPageWithText(async (p, dom) => {
  const unanswered = fake.unanswered.length;
  await PUMP.loadWhole(G);
  await SCENE.open(G, heldVersionOfG(), { heldB: true });
  const article = shownIn(p.paneB, 'b');
  /** a key at the pane the focus stands in, as the platform delivers it, and what the status region said once its words land — an emptying, which a say again makes first, not counted */
  const press = async (/** @type {string} */ key, /** @type {{mod?: boolean, shift?: boolean}} */ m = {}) => {
    const n = p.said.length;
    const took = await KEYS.dispatch(/** @type {any} */ ({ type: 'keydown', key, keyCode: 0, isComposing: false, repeat: false, metaKey: !!m.mod && KEYS.MAC, ctrlKey: !!m.mod && !KEYS.MAC, shiftKey: !!m.shift, altKey: false, preventDefault() {}, target: p.at() === 'pane A' ? p.paneA : p.paneB }), { where: 'scene', byKey: true });
    await new Promise((r) => setTimeout(r, 0));
    return { took, hint: HINT.standing()?.id ?? null, said: p.said.slice(n).filter(Boolean) };
  };
  /** each sending act's chord, as `press` takes it */
  const SENDING = /** @type {Array<[string, {mod: boolean, shift?: boolean}]>} */ ([['k', { mod: true }], ['A', { mod: true, shift: true }], ['C', { mod: true, shift: true }]]);
  const NOT = 'B3.held-version.not-current', IN = 'B3.held-version.in-current';
  p.paneB.focus();
  assert.equal(p.at(), 'pane B');
  /** @type {Array<[string, {pos: number, width: number}, string]>} each selection, the span T-LAYER reads it as, and the reason it keys */
  const CASES = [['Held words', { pos: 17, width: 10 }, NOT], ['passage', { pos: 33, width: 7 }, IN], ['words. Its', { pos: 22, width: 10 }, NOT]];
  for (const [words, span, why] of CASES) {
    selectWords(dom, article, words);
    assert.deepEqual(LAYER.selectionIn(article)?.span, { addr: G, ...span }, `"${words}": the selection read where it stands in the held version`);
    assert.equal(SCENE.heldVersionReason(), why, `"${words}": the reason its selection keys`);
    for (const [key, m] of SENDING) {
      HINT.act();
      assert.deepEqual(await press(key, m), { took: true, hint: why, said: [heard(hintSentences(why).whole)] }, `"${words}", ${m.shift ? 'Mod+Shift+' : 'Mod+'}${key.toUpperCase()}: that reason its hint, a sentence, said`);
    }
    assert.deepEqual(await press('q'), { took: true, hint: why, said: [heard(hintSentences(why).whole)] }, `"${words}", a printable key: the same reason, said again at the press`);
    const space = await press(' ');
    assert.deepEqual([space.took, space.hint, space.said.length], [true, 'F.swallow.space', 1], `"${words}", Space: K-9's own line`);
  }
  assert.deepEqual([HOST.currentState(), SCENE.isOpen()], [null, true], 'no overlay opened, the scene standing');
  dom.document.selection.removeAllRanges();
  HINT.act();
  assert.deepEqual([SCENE.heldVersionReason(), (await press('k', { mod: true })).hint, (await press('q')).hint], [null, 'L.seam.link-to', IN], 'no selection in the held version: the slot\'s own reason; a printable key the reason its span focus keys — its first span, the current text holding its words too — never K-9\'s line');
  selectWords(dom, article, 'Held words');
  p.paneA.focus();
  assert.deepEqual([p.at(), SCENE.heldVersionReason(), (await press('k', { mod: true })).hint], ['pane A', null, 'L.seam.link-to'], 'the focus in pane A: the slot\'s own reason');
  SCENE.close();
  await SCENE.open(G, heldVersionOfG());
  const plain = shownIn(p.paneB, 'b');
  p.paneB.focus();
  selectWords(dom, plain, 'Held words');
  assert.deepEqual([SCENE.heldVersionReason(), (await press('k', { mod: true })).hint], [null, 'L.seam.link-to'], 'a scene not the moved scene: the slot\'s own reason');
  assert.deepEqual(fake.unanswered.slice(unanswered), []);
}));

test('the moved scene\'s last held line discarded, the scene staying, its end line names the key that closes the scene as the platform draws it — "Esc", never a token — after the draft\'s name (D6 BM-16; style S21; issue #627)', () => onPage(async () => {
  const unasked = fake.unanswered.length, session = { session: 's-1', principal: 1, account: '1.0.1' };
  /** @type {unknown[]} the lines the shell holds for the session, as `held(session)` lists them */
  let rows = [{ ...MOVED_ROW[0], base: 1, frame: { ...MOVED_ROW[0].frame, as_of: 1, id: 'p.1' }, refusal: { kind: 'refused', name: 'arrangement_moved', status: 200, code: 'arrangement_moved', detail: null, op: 'insert', site: { as_of: 1, current: 3 }, body: null }, sendable: false }];
  const heldKey = FAKE.keyOf('held', { session: 's-1' }), dropKey = FAKE.keyOf('resolve', { session: 's-1', held: 1, act: 'drop' });
  Object.defineProperty(script, heldKey, { configurable: true, enumerable: true, get: () => ({ result: rows }) });
  Object.assign(script, { [dropKey]: { result: {} } });
  /** @type {Array<[string, string]>} each line said in the one line: its string, and its words as drawn */
  const lines = [];
  const flush = async () => { for (let i = 0; i < 8; i++) await new Promise((r) => setImmediate(r)); };
  try {
    await PUMP.loadWhole(G);
    REC.setSession(/** @type {any} */ ({ ...session, writes: true }));
    MACHINE.handIn();
    await flush();
    assert.equal(FACES.cornerFace(G)?.line.id, 'B3.moved', 'the moved face stands at the draft\'s corner');
    await SCENE.open(G, heldVersionOfG(), { heldB: true });
    assert.equal(SCENE.isOpen(), true, 'the moved scene stands');
    FACES.readers({ line: (words, id) => { lines.push([id, runsText(asRuns(words))]); } });
    rows = [];
    assert.equal(FACES.faceAct(G, 'discard'), true, 'the face\'s discard taken');
    await flush();
    const none = lines.find(([id]) => id === 'B3.held.none');
    assert.deepEqual(none, ['B3.held.none', `nothing is held for ${LAYER.boxName(G).name} now\u00a0— Esc closes this`], `its end line, its key drawn: ${JSON.stringify(lines)}`);
    assert.deepEqual(fake.unanswered.slice(unasked), []);
  } finally {
    MACHINE._reset(); FACES.readers({ line: (words) => FOCUS.say(words) }); REC.setSession(session);
    delete script[heldKey]; delete script[dropKey];
  }
}));

test('each pane is named by its corner\'s first item, then its address: the bar\'s hidden words its kind — "draft" at a draft, "published" at an edition — and its corner opening with that kind in its slot (issue #423\'s design decision: "A scene pane has no item, so its region is named the same way"; FP-33)', () => onPage(async (p) => {
  const unanswered = fake.unanswered.length;
  await SCENE.open(WRITING, B);
  assert.ok(p.bar.innerHTML.includes(`<span id="sceneA-kind" hidden>${esc(t('F.kind.draft'))}</span>`) && p.bar.innerHTML.includes(`<span id="sceneB-kind" hidden>${esc(t('F.published'))}</span>`), `the bar's hidden words: each pane's kind — ${p.bar.innerHTML}`);
  assert.deepEqual([p.paneA.attrs['aria-labelledby'], p.paneB.attrs['aria-labelledby']], ['sceneA-kind sceneA-name', 'sceneB-kind sceneB-name'], 'each pane named by its kind, then its address');
  assert.ok(/<div class="corner[^"]*"[^>]*><span class="kind" data-kind="draft"/.test(p.paneA.innerHTML) && /<div class="corner[^"]*"[^>]*><span class="kind" data-kind="published"/.test(p.paneB.innerHTML), `each corner opens with its kind: ${p.paneA.innerHTML.slice(0, 300)} | ${p.paneB.innerHTML.slice(-600)}`);
  assert.deepEqual(fake.unanswered.slice(unanswered), []);
}));

test('a pane\'s kind is said once in the status region where its corner\'s slot fills while the platform\'s focus stands in the pane — a record opened with its kind being read, its box listed a draft — the corner and the bar\'s words its name leads with written again in place; nothing said where the focus stands elsewhere (issue #423\'s design decision: "If it fills while the focus is in that document, the status region says so once"; FP-36)', () => onPage(async (p) => {
  const X = '1.0.1.0.72', Y = '1.0.1.0.73';
  const listing = (/** @type {Array<{doc: string, kind: string}>} */ extra) => REC.takeIndex(/** @type {any} */ ({ docs: [{ doc: A, kind: 'edition', label: 'a', standing: 'public' }, { doc: B, kind: 'edition', label: 'b', standing: 'public' }, ...extra.map((x) => ({ ...x, label: x.doc, standing: 'yours_to_read' }))], counts: [{ account: '1.0.1', documents: 2 + extra.length }], state: { arm: 'complete' } }));
  /** a record the page holds of a document whose kind nothing has told: listed nowhere, no metadata read */
  const untold = (/** @type {string} */ addr) => ({ ...draftOf(addr, 'An untold note.'), kind: /** @type {const} */ ('unknown'), derived: { from: addr, rows: [], edits: 0, at: null } });
  try {
    await SCENE.open(A, untold(X));
    assert.ok(/<span class="kind pending" data-kind="reading"/.test(p.paneB.innerHTML) && p.bar.innerHTML.includes(`<span id="sceneB-kind" hidden>${esc(t('L.slot.reading'))}</span>`), 'its kind being read: the slot an empty box, its name leading with that');
    p.paneB.focus();
    const told = p.said.length;
    SCENE.markKept();
    assert.deepEqual(p.said.slice(told), [], 'nothing told yet: nothing said');
    listing([{ doc: X, kind: 'draft' }]);
    SCENE.markKept();
    SCENE.markKept();
    assert.deepEqual(p.said.slice(told), [t('F.kind.draft')], 'its slot filled under the focus: "draft", said once');
    assert.ok(p.cornerB.innerHTML.startsWith('<span class="kind" data-kind="draft"'), `its corner written again in place: ${p.cornerB.innerHTML}`);
    SCENE.close();
    await SCENE.open(A, untold(Y));
    p.paneA.focus();
    const after = p.said.length;
    listing([{ doc: X, kind: 'draft' }, { doc: Y, kind: 'draft' }]);
    SCENE.markKept();
    assert.deepEqual(p.said.slice(after), [], 'filled while the focus stands in the other pane: nothing said');
  } finally { listing([]); }
}));

/** the platform laying the scene out wide enough for its panes to stand side by side 600 px wide each, with no padding and an 8 px gap, which fits both corners compact beside their columns (`fitOf`): the act that lays them out where the platform lays out none */
function compactFit(/** @type {ReturnType<typeof page>} */ p) {
  const was = globalThis.getComputedStyle;
  p.root.clientWidth = 2 * 600 + SCENE.SIDE_GAP;
  globalThis.getComputedStyle = /** @type {any} */ (() => ({ paddingLeft: '0px', paddingRight: '0px', columnGap: '8px' }));
  return () => { if (was) globalThis.getComputedStyle = was; else delete (/** @type {any} */ (globalThis)).getComputedStyle; };
}
/** a click at an element of a pane's corner as the platform hands it to the pane: the one it makes from Enter or Space at a button where `byKey`, else a pointer's */
const clickIn = (/** @type {ReturnType<typeof page>} */ p, /** @type {'a' | 'b'} */ side, /** @type {unknown} */ target, /** @type {boolean} */ byKey) =>
  p.paneOn[side].click({ type: 'click', detail: byKey ? 0 : 1, target, currentTarget: side === 'a' ? p.paneA : p.paneB });
/** a pane's corner's Tab stops, each by the act it is (T-LAYER's `cornerAct`), the corner's own element as `corner` */
const stopsIn = (/** @type {any} */ c, /** @type {any[]} */ acts) => [c, ...acts].filter((x) => x.getAttribute('tabindex') === '0').map((x) => (x === c ? 'corner' : LAYER.cornerAct(x)));

test('a pane\'s corner\'s acts are buttons, each act its click\'s: each line of the corner\'s acts a toolbar of its own whose Tab stop is its first act — the kept line, its kept word and its second act; the glyph\'s line — its element none; the kept word a disclosure of the draft\'s kept statement, the click the platform makes from Enter or Space at it, or a pointer\'s, opening the statement and the next closing it, the focus kept on the word written again; and in the corner a glyph opened whole the kept word\'s click opens the statement still, the corner standing whole until the words the glyph opened are clicked; the scene\'s own keys take no Enter there (D5 K-57, K-74; B3-S2; FP-20, FP-26)', () => onPage(async (p) => {
  const restore = compactFit(p);
  WRITE.setKept(WRITING, { word: 'kept', reason: null });
  try {
    await SCENE.open(WRITING, B);
    const c = p.cornerA, acts = p.acts.a, keyed = (/** @type {string} */ k) => acts.find((b) => LAYER.cornerAct(b) === k) || null;
    assert.ok(String(c.className).split(' ').includes('compact'), `the panes fitted compact: ${c.className}`);
    assert.equal(SCENE.fitted()?.stacked, false, 'side by side');
    assert.deepEqual([acts.map(LAYER.cornerAct), c.getAttribute('role'), stopsIn(c, acts)], [['kept', 'history', 'whole'], 'group', ['kept', 'whole']],
      'the draft\'s corner: its kept word with its second act on the kept line, and the glyph that opens it whole on its own — two lines of acts, each its stop its first act, the corner a group of them, its element no stop (skep-frontend #585)');
    keyed('kept').focus();
    assert.deepEqual([SCENE.key('Enter'), LAYER.statementOpen(WRITING)], [false, false], 'Enter at the kept word: the scene\'s own keys take none of it, and nothing opens');
    clickIn(p, 'a', keyed('kept'), true);
    assert.deepEqual([LAYER.statementOpen(WRITING), keyed('kept')?.getAttribute('aria-expanded'), p.at(), c.innerHTML.includes('class="kept-statement"')], [true, 'true', keyed('kept')?.id, true],
      'the platform\'s click from Enter or Space at the kept word: its statement opened in the corner, the word saying so, the focus on the word written again');
    clickIn(p, 'a', keyed('kept'), false);
    assert.deepEqual([LAYER.statementOpen(WRITING), keyed('kept')?.getAttribute('aria-expanded'), p.at()], [false, 'false', keyed('kept')?.id], 'a pointer\'s click: closed again');
    clickIn(p, 'a', keyed('whole'), false);
    assert.deepEqual([String(c.className).split(' ').includes('open'), keyed('whole')?.getAttribute('aria-expanded')], [true, 'true'], 'the glyph\'s click opens the corner whole, the words it opened saying so');
    clickIn(p, 'a', keyed('kept'), false);
    assert.deepEqual([LAYER.statementOpen(WRITING), String(c.className).split(' ').includes('open')], [true, true], 'the kept word\'s click in the corner opened whole: the statement opened, the corner standing whole');
    clickIn(p, 'a', keyed('whole'), true);
    assert.deepEqual([String(c.className).split(' ').includes('open'), LAYER.statementOpen(WRITING)], [false, true], 'the words the glyph opened, clicked: the corner compact again, the statement standing');
  } finally { LAYER.openStatement(WRITING, false); WRITE.setKept(WRITING, null); restore(); }
}, { acts: true }));

test('at a pane\'s corner\'s act the dispatch leaves Enter, Space and Shift+Space to the button, raising no line, and takes an auto-repeat, making nothing; ← and → walk the line\'s acts — the kept line\'s word and its second act, never across to the next line — its stop following the focus, the scene standing at its first act and its last; a printable key but Space at the corner of a pane that is its draft\'s editor answered by the way back to the draft\'s text, never K-9\'s line — the corner routed as a corner, never as its pane (D5 K-9, K-57, K-61; B3-S13; FP-20; skep-frontend #585, #556)', () => onPage(async (p) => {
  const restore = compactFit(p);
  WRITE.setKept(WRITING, { word: 'kept', reason: null });
  /** a key at an act of pane A's corner, as the app hands it to the dispatch there */
  const at = (/** @type {any} */ target, /** @type {string} */ key, /** @type {object} */ mods = {}) => KEYS.dispatch({ ...keyOf(key), repeat: false, target, ...mods }, { where: 'scene', byKey: true });
  try {
    await SCENE.open(WRITING, B);
    const acts = p.acts.a, keyed = (/** @type {string} */ k) => acts.find((b) => LAYER.cornerAct(b) === k) || null;
    keyed('kept').focus();
    HINT.act();
    for (const [key, mods, what] of /** @type {Array<[string, object, string]>} */ ([['Enter', {}, 'Enter'], [' ', {}, 'Space'], [' ', { shiftKey: true }, 'Shift+Space']])) {
      assert.equal(await at(keyed('kept'), key, mods), false, `${what} at the kept word: the button's own`);
    }
    assert.deepEqual([HINT.standing(), LAYER.statementOpen(WRITING), SCENE.isOpen()], [null, false, true], 'no line raised and nothing made by the dispatch — the platform\'s click makes the act — the scene standing');
    assert.equal(await at(keyed('kept'), ' ', { repeat: true }), true, 'an auto-repeat of Space: taken');
    assert.deepEqual([HINT.standing(), LAYER.statementOpen(WRITING)], [null, false], 'and making nothing');
    assert.equal(await at(keyed('kept'), 'ArrowRight'), true);
    assert.deepEqual([p.at(), stopsIn(p.cornerA, acts)], [keyed('history')?.id, ['history', 'whole']], '→: the focus on the kept line\'s second act, the line\'s stop following it, the glyph\'s line keeping its own');
    assert.equal(await at(keyed('history'), 'ArrowRight'), true);
    assert.deepEqual([p.at(), SCENE.isOpen()], [keyed('history')?.id, true], '→ at the line\'s last act: taken, nothing further — never on the next line\'s glyph — the scene standing');
    assert.equal(await at(keyed('history'), 'ArrowLeft'), true);
    assert.equal(await at(keyed('kept'), 'ArrowLeft'), true);
    assert.deepEqual([p.at(), stopsIn(p.cornerA, acts), SCENE.isOpen()], [keyed('kept')?.id, ['kept', 'whole'], true], '← back to the kept word, then ← at the line\'s first act: the focus there, the scene standing — never its close');
    assert.equal(await at(keyed('kept'), 'q'), true);
    assert.equal(HINT.standing()?.id, 'B3.caret.back', 'a printable key at the editor pane\'s corner: the way back to the draft\'s text');
  } finally { HINT.act(); LAYER.openStatement(WRITING, false); WRITE.setKept(WRITING, null); restore(); }
}, { acts: true }));

test('a pane\'s corner holding acts is returned to on its line\'s stop: left by WHOLE BOARD from its kept word, the scene\'s entry records the corner, and Back reopens it with the focus on the corner\'s first act written again, never on the corner\'s element (D5 K-57; FP-20, FP-25)', () => onPage(async (p) => {
  WRITE.setKept(WRITING, { word: 'kept', reason: null });
  try {
    await onTrail(p);
    assert.equal(await GO.toScene(WRITING, B), true);
    await flown();
    const acts = p.acts.a, kept = () => acts.find((b) => LAYER.cornerAct(b) === 'kept') || null;
    assert.deepEqual([acts.map(LAYER.cornerAct), stopsIn(p.cornerA, acts)], [['kept', 'history'], ['kept']], 'the draft\'s corner beside its column holds one line of acts, its kept word and its second act, the line\'s stop its kept word');
    kept().focus();
    const board = GO.wholeBoard(); await flown(); await board;
    assert.deepEqual([SCENE.isOpen(), TRAIL.all().find((e) => e.scene)?.scene?.left?.stop], [false, 'a:corner'], 'WHOLE BOARD from the kept word: the scene ended, its entry recording the stop the focus stood on, the corner');
    const back = GO.back(); await flown(); await back;
    assert.deepEqual([SCENE.isOpen(), p.at()], [true, kept()?.id], 'Back reopens it, the focus on the corner\'s stop, its kept word written again');
    assert.notEqual(p.at(), p.cornerA.id, 'never the corner\'s element, which holds no stop');
  } finally { WRITE.setKept(WRITING, null); }
}, { acts: true }));

Object.assign(script, compared(A, A_TEXT, A, A_TEXT, [[1, 1, A_TEXT.length]]));

test('a scene on one document in both panes opens — each pane the document, named by its own head, the two ends level at the passage held — and leaving records two spots, one per pane, each pane where the reader scrolled it; a reopening opens it on the one document twice (the survey\'s §6 #2, tufte\'s (4))', () => onPage(async (p) => {
  p.item.focus();
  await SCENE.open(A, A, { posA: 14, widthA: 3 });
  assert.equal(SCENE.isOpen(), true, 'the scene shows');
  const panes = SCENE.panes();
  assert.deepEqual([panes?.a.src, panes?.b.src, panes?.a.shows, panes?.b.shows, panes?.a.derived, panes?.b.derived], [A, A, A, A, false, false]);
  assert.deepEqual(SCENE.pairs()?.level, { a: 14, b: 14 }, 'the held passage level with itself');
  assert.deepEqual([p.headA.id, p.headB.id, p.paneA.attrs['aria-labelledby'], p.paneB.attrs['aria-labelledby']], ['sceneA-name', 'sceneB-name', 'sceneA-kind sceneA-name', 'sceneB-kind sceneB-name'], 'each pane named by its kind and its own head');
  p.paneA.scrollTop = 30; p.paneB.scrollTop = 90;
  const left = SCENE.asLeft();
  assert.ok(left && left.spots && left.spots.a !== left.spots.b, 'two spots, one per pane');
  assert.deepEqual([left.panes.a.src, left.panes.b.src, p.paneA.scrollTop, p.paneB.scrollTop], [A, A, 30, 90], 'each pane where the reader scrolled it');
  SCENE.close();
  await SCENE.reopen({ a: A, b: A, held: { posA: 14, widthA: 3 }, left });
  assert.deepEqual([SCENE.isOpen(), SCENE.panes()?.a.src, SCENE.panes()?.b.src, SCENE.pairs()?.level], [true, A, A, { a: 14, b: 14 }], 'reopened on the one document twice, level as before');
  assert.deepEqual(fake.unanswered, []);
}));

