    const reason = sentence('L.history.unanswered', { board: t('L.mirror.board.name', { node: '1', origin: '' }) }), n = p.said.length;
    const target = { closest: (/** @type {string} */ s) => (s === '.corner' || s === '[data-history]' ? {} : null) };
