  await keyAt(p.paneA, 'w');
  assert.deepEqual([LAYER.caret(), WRITE.edits(E1).map((e) => [e.pos, e.text])], [{ addr: E1, pos: 6, live: true }, [[4, 'q'], [5, 'w']]], 'the next printable key returns the caret and types there');
